# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HUNEYN GAZVESİ VE TAİF KUŞATMASI (HİCRİ 8 / MİLADİ 630)</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">HUNEYN GAZVESİ VE KUŞATMA SÜRECİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• İttifak: Hevâzin ve Sakîf kabileleri (Komutan: Mâlik b. Avf).</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• Huneyn Zaferi: Bozguna uğrayan düşman Taif surlarına sığındı.</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• Taif Kuşatması: Yaklaşık 20 gün sürdü, kaleye girilemedi.</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• Askerî Yenilik: İslam tarihinde ilk kez MANCINIK ve DEBBÂBE.</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• İstişare: Haram ayların yaklaşmasıyla kuşatma kaldırıldı.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">NEBEVÎ STRATEJİ VE MERHAMET DUASI</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• Hz. Peygamber intikam yerine hidayet ve barışı hedefledi.</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• Dua: \'Allah\'ım! Sakîf\'e hidayet ver ve onları bize getir!\'</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• Ci\'râne\'de esirlerin (6.000 kişi) karşılıksız serbest bırakılması.</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• Hevâzin lideri Mâlik b. Avf\'ın İslam\'ı kabul etmesi.</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• Sonuç: Taif askeri ve ekonomik olarak yalnızlaştı.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Peygamber hem Mekke döneminde taşlandığında hem de Taif Kuşatması\'nda Sakîf kabilesi için hidayet duası etmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">URVE B. MES\'ÛD\'UN ŞEHADETİ VE SAKÎF HEYETİ (HİCRİ 9 / 630)</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">URVE B. MES\'ÛD ES-SEKAFÎ\'NİN ÖRNEKLİĞİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• Taif\'in saygın liderlerinden olup kendi isteğiyle iman etti.</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• Kavmini İslam\'a davet etmek için cesaretle Taif\'e döndü.</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• Sabah vaktinde ezan okurken okla vurularak şehit edildi.</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• Şehadeti Taif halkında büyük bir vicdan muhasebesi başlattı.</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• Çevresi İslamlaşan Taif, barış için heyet göndermeye karar verdi.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">SAKÎF HEYETİ\'NİN MEDİNE\'DE AĞIRLANMASI</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• Tarih: Hicri 9. Yıl Ramazan ayı (Heyetler Yılı).</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• Heyet Başkanı: Abdüyâlîl b. Amr (6 kişilik temsilci heyeti).</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• Konaklama: Mescid-i Nebevî\'nin içinde özel çadır kuruldu.</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• Amaç: Kur\'an\'ı dinlemeleri ve İslam kardeşliğini görmeleri.</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• Halid b. Said b. Âs, taraflar arasında elçilik görevini yürüttü.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Peygamber\'in Taif heyetini Mescid-i Nebevî\'de ağırlaması, eğitici ve kuşatıcı tebliğ yönteminin en güzel örneğidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TEVHİT İLKESİNDE KARARLILIK VE TAİF\'İN İSLAMLAŞMASI</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">SAKÎF HEYETİ\'NİN TALEPLERİ VE PEYGAMBERİMİZİN CEVABI</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• Talep 1: Lât putunun 3 yıl / 1 ay yıkılmaması -&gt; REDDEDİLDİ.</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• Talep 2: Faiz, içki ve zinaya izin verilmesi -&gt; REDDEDİLDİ.</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• Talep 3: Namazdan muaf tutulma -&gt; REDDEDİLDİ.</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• Nebevi İlke: \'Rükûsuz (namazsız) bir dinde hayır yoktur!\'</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• Kabul Edilen: Putu kendi elleriyle yıkmama (Muğîre gönderildi).</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">TAİF\'TE İSLAM DÜZENİNİN KURULMASI</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• Lât Putunun Yıkımı: Muğîre b. Şu\'be ve Ebû Süfyân yıktı.</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• Genç Vali ve İmam: Osman b. Ebü\'l-Âs es-Sekafî atandı.</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• Peygamber Tavsiyesi: \'Namazda cemaatin en zayıfını gözet!\'</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Sadakat: Hz. Ebû Bekir dönemindeki dinden dönme (ridde)</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• olaylarında Taif halkı İslam\'a bağlılığını korudu.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Peygamber insanlara karşı son derece merhametli ve esnek davranmış, ancak tevhit ve farzlardan taviz vermemiştir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
